import java.util.*;
import java.io.*;
import java.math.*;

public class Main {
    static final BigInteger MOD = new BigInteger("998244353");
    static void error() {
        System.out.println(-1);
    }
    public static void main(String[] args) throws IOException {
        BufferedReader reader = new BufferedReader(new InputStreamReader(System.in));
        PrintWriter writer = new PrintWriter(System.out);
        StringTokenizer tokenizer = new StringTokenizer(reader.readLine());
        int testCases = 1;
        // testCases = Integer.parseInt(tokenizer.nextToken());
        while (testCases-- > 0) {
            tokenizer = new StringTokenizer(reader.readLine());
            long n = Long.parseLong(tokenizer.nextToken());
            long m = Long.parseLong(tokenizer.nextToken());
            tokenizer = new StringTokenizer(reader.readLine());
            long l = Long.parseLong(tokenizer.nextToken());
            long r = Long.parseLong(tokenizer.nextToken());
            long rangeLength = r - l;
            long evenCount = rangeLength / 2 + 1;
            long oddCount = (rangeLength + 1) / 2;
            if ((n * m) % 2 == 1) {
                BigInteger base = BigInteger.valueOf(rangeLength + 1);
                BigInteger res = base.modPow(BigInteger.valueOf(n * m), MOD);
                writer.println(res);
            } else {
                BigInteger powEvenOdd = BigInteger.valueOf(evenCount + oddCount).modPow(BigInteger.valueOf(n * m), MOD);
                BigInteger powEvenMinusOdd = BigInteger.valueOf(evenCount - oddCount).modPow(BigInteger.valueOf(n * m), MOD);
                BigInteger sum = powEvenOdd.add(powEvenMinusOdd);
                BigInteger invTwo = BigInteger.valueOf(2).modInverse(MOD);
                BigInteger result = sum.multiply(invTwo).mod(MOD);
                writer.println(result);
            }
        }
        writer.flush();
    }
}
